var t=`0210-fabada-asturiana`;var n=`world-0210`;var i=`ES`;var s=`southern-europe`;var r=4;var o=152;var d={en:`Fabada Asturiana`,ua:`Фабада астуріана`};var l={en:`Uses available butter beans in place of the specific Asturian fabes; cured chorizo and blood sausage are included.`,ua:`Замість астурійської квасолі fabes використано доступну в каталозі білу квасолю; додано чорізо й кров’яну ковбасу.`};var u=[{en:`Soak the dried butter beans overnight, drain, then start cooking them in fresh water until nearly tender, typically 1½–2 hours. Maintain a gentle simmer.`,ua:`Замочіть суху квасолю на ніч, злийте воду та варіть у свіжій до майже повної м’якості приблизно 1,5–2 години на малому вогні.`,t:[`boiling`],m:115,i:[[`butter-beans`,400,`g`],[`water`,1500,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`chorizo-cured`,170,`g`],[`blood-sausage`,180,`g`],[`pork-shoulder`,250,`g`],[`bacon`,120,`g`],[`saffron-threads`,.3,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:2,i:[[`table-salt`,null,`to_taste`]]}];var g={slug:t,id:n,country:`ES`,region:s,servings:4,minutes:152,title:d,text:l,steps:u};export{i as country,g as default,n as id,o as minutes,s as region,r as servings,t as slug,u as steps,l as text,d as title};